  "Every level on the platform comes from the students’ data. The more complete it is, the more the levels, groups and reports can be trusted. Fill the gaps first.": "كل مستوى على المنصة يأتي من بيانات الطلاب. كلما اكتملت زادت الثقة في المستويات والمجموعات والتقارير. أكمل النواقص أولًا.",
  "Every question as a learning object: skill, standard, MAP domain, difficulty, DOK, reading level and the misconception behind each wrong option. Automatic values keep their source; disagreements and duplicates wait for a person's review. Nothing is published automatically.": "كل سؤال كوحدة تعلّم: المهارة، والمعيار، ومجال MAP، والصعوبة، وDOK، ومستوى القراءة، والفهم الخاطئ وراء كل خيار خاطئ. القيم التلقائية تحتفظ بمصدرها؛ والتعارضات والمكررات تنتظر مراجعة شخص. لا يُنشر شيء تلقائيًا.",
  "Every report in one place: for families (approved by the school admin before they are sent), MAP in NWEA style, practice on the platform, the Diagnostic and reading fluency. Each one prints or saves as PDF.": "كل التقارير في مكان واحد: للأسر (يعتمدها مدير المدرسة قبل الإرسال)، وMAP بأسلوب NWEA، والتدريب على المنصة، والاختبار التشخيصي، وطلاقة القراءة. كل تقرير يُطبع أو يُحفظ PDF.",
