  "Write or paste my rubric": "اكتب سلّم التقدير أو الصقه",
  "Paste a table from Word, Excel or Google Docs (first row: the levels with their points; first column: the criteria), or type your rubric line by line with a blank line between criteria.": "الصق جدولًا من Word أو Excel أو Google Docs (الصف الأول: المستويات مع درجاتها؛ العمود الأول: المعايير)، أو اكتب سلّم التقدير سطرًا سطرًا مع سطر فارغ بين المعايير.",
