  "Level headers like “Exemplary (4)”, “4 - Exemplary” or “Exemplary 4 pts”; a criterion's description can go in parentheses after its name.": "عناوين المستويات مثل “Exemplary (4)” أو “4 - Exemplary” أو “Exemplary 4 pts”؛ ويمكن كتابة وصف المعيار بين قوسين بعد اسمه.",
