  "read as typed lines": "قُرئ كأسطر مكتوبة",
  "Your wording is kept with the task and also given to the AI when you use Grade with AI.": "تُحفظ صياغتك مع المهمة وتُرسل أيضًا إلى الذكاء الاصطناعي عند استخدام التصحيح بالذكاء الاصطناعي.",
  "Save this rubric for later": "احفظ سلّم التقدير لاستخدامه لاحقًا",
  "Paste a table or type your rubric first.": "الصق جدولًا أو اكتب سلّم التقدير أولًا.",
  "Row {line}: the level header “{text}” needs points, e.g. “Exemplary (4)” or “4 - Exemplary”.": "الصف {line}: عنوان المستوى “{text}” يحتاج إلى درجات، مثل “Exemplary (4)” أو “4 - Exemplary”.",
  "Row {line}: “{text}”: points must be a whole number from 0 to 100.": "الصف {line}: “{text}”: يجب أن تكون الدرجات عددًا صحيحًا من 0 إلى 100.",
  "Row {line}: the first row needs 2 to 6 level headers with points, e.g. “Beginning (1)”, “Developing (2)”…": "الصف {line}: يحتاج الصف الأول إلى 2 إلى 6 عناوين مستويات مع درجاتها، مثل “Beginning (1)” و“Developing (2)”…",
  "Row {line}: a rubric has 2 to 6 levels (this one has {n}).": "الصف {line}: لسلّم التقدير من 2 إلى 6 مستويات (هذا فيه {n}).",
  "Row {line}: write the criterion's name in the first column.": "الصف {line}: اكتب اسم المعيار في العمود الأول.",
  "Row {line}: there is text in a column without a level header.": "الصف {line}: يوجد نص في عمود بلا عنوان مستوى.",
  "Add a row for each criterion under the level headers.": "أضف صفًا لكل معيار تحت عناوين المستويات.",
  "Line {line}: separate the level name from its description with “-” or “:”, e.g. 3 Proficient - opinion with two reasons.": "السطر {line}: افصل اسم المستوى عن وصفه بـ “-” أو “:”، مثل: 3 Proficient - opinion with two reasons.",
  "Line {line}: a level needs points, e.g. 3 Proficient - opinion with two reasons.": "السطر {line}: المستوى يحتاج إلى درجات، مثل: 3 Proficient - opinion with two reasons.",
  "Line {line}: points must be a whole number from 0 to 100.": "السطر {line}: يجب أن تكون الدرجات عددًا صحيحًا من 0 إلى 100.",
  "Line {line}: the level needs a name, e.g. 3 Proficient - opinion with two reasons.": "السطر {line}: المستوى يحتاج إلى اسم، مثل: 3 Proficient - opinion with two reasons.",
  "Line {line}: write the criterion's name, e.g. Ideas: A clear opinion with reasons.": "السطر {line}: اكتب اسم المعيار، مثل: Ideas: A clear opinion with reasons.",
  "Line {line}: start with the criterion's name, e.g. Ideas: A clear opinion with reasons.": "السطر {line}: ابدأ باسم المعيار، مثل: Ideas: A clear opinion with reasons.",
  "Line {line}: “{name}” needs 2 to 6 levels (it has {n}).": "السطر {line}: “{name}” يحتاج إلى 2 إلى 6 مستويات (فيه {n}).",
  "Line {line}: “{name}” has no levels. Under it, write one level per line, e.g. 3 Proficient - opinion with two reasons.": "السطر {line}: “{name}” بلا مستويات. اكتب تحته مستوى واحدًا في كل سطر، مثل: 3 Proficient - opinion with two reasons.",
  "A rubric has at most 10 criteria (this one has {n}).": "لسلّم التقدير 10 معايير على الأكثر (هذا فيه {n}).",
  "The rubric needs at least one level worth more than 0 points.": "يحتاج سلّم التقدير إلى مستوى واحد على الأقل بدرجة أكبر من 0.",
  "Two criteria are both called “{name}”.": "يوجد معياران بالاسم نفسه “{name}”.",
  "Notes for AI grading (optional)": "ملاحظات للتصحيح بالذكاء الاصطناعي (اختياري)",
  "e.g. Focus on the thesis; this class just learned paragraphs.": "مثال: ركّز على الفكرة الرئيسة؛ هذا الصف تعلّم الفقرات للتو.",
  "Only used to guide the AI's suggestions for you. Never write student names. You can change it on the grading page.": "تُستخدم فقط لتوجيه اقتراحات الذكاء الاصطناعي لك. لا تكتب أسماء الطلاب أبدًا. يمكنك تغييرها في صفحة التصحيح.",
  "Saved with the task for every essay. The AI reads the essay twice and compares; this counts as one AI grading.": "تُحفظ مع المهمة لكل المقالات. يقرأ الذكاء الاصطناعي المقال مرتين ويقارن، ويُحتسب ذلك تصحيحًا واحدًا بالذكاء الاصطناعي.",
  "Sent to the AI: the task, its grade, word counts and time limit, the rubric (and your own rubric wording), your notes and the essay — never the student's name.": "يُرسل إلى الذكاء الاصطناعي: المهمة وصفّها وعدد الكلمات والوقت المحدد وسلّم التقدير (وصياغتك الخاصة له) وملاحظاتك والمقال — ولا يُرسل اسم الطالب أبدًا.",
  "High confidence": "ثقة عالية",
  "Medium confidence": "ثقة متوسطة",
  "Low confidence": "ثقة منخفضة",
  "Replace your comment with the AI's suggested feedback?": "هل تريد استبدال تعليقك بالملاحظات التي يقترحها الذكاء الاصطناعي؟",
  "Clear highlight": "إزالة التظليل",
  "Quote not found in the essay": "لم يُعثر على الاقتباس في المقال",
