  "Reading sheets…": "جارٍ قراءة الأوراق…",
  "Line up the four black corner squares inside the frame": "ضع المربعات السوداء الأربعة في الزوايا داخل الإطار",
  "Camera not available. Choose images instead.": "الكاميرا غير متاحة. اختر صورًا بدلًا من ذلك.",
  "Scanned PDF? Save its pages as images (JPG or PNG) and choose them here.": "لديك ملف PDF ممسوح ضوئيًا؟ احفظ صفحاته كصور (JPG أو PNG) ثم اخترها هنا.",
  "Photos are read on this device and are never uploaded.": "تُقرأ الصور على هذا الجهاز ولا تُرفع أبدًا.",
  "Could not open this image": "تعذّر فتح هذه الصورة",
  "Fill the circle completely with a dark pencil or pen": "ظلّل الدائرة بالكامل بقلم رصاص داكن أو قلم حبر",
  "% correct, discrimination D (upper 27% minus lower 27% of the students: 0.20 or more is good), the most chosen wrong option, and flags for items to review.": "نسبة الإجابات الصحيحة، ومعامل التمييز D (أعلى 27% من الطلاب ناقص أدنى 27%: ‎0.20 فأكثر جيد)، والخيار الخاطئ الأكثر اختيارًا، وتنبيهات للأسئلة التي تحتاج إلى مراجعة.",
  "Adapted for international English Grade 6 reading.": "مُكيَّف لقراءة اللغة الإنجليزية للصف السادس في المدارس العالمية.",
