  "No NAFS tests waiting": "لا توجد اختبارات نافس بانتظارك",
  "Your teacher will add NAFS tests here.": "سيضيف معلمك اختبارات نافس هنا.",
  "Your score shows here after your teacher shares it.": "تظهر درجتك هنا بعد أن يشاركها معلمك.",
  "Practice scores show right away under My practice. My results is only for official NAFS tests your teacher has released.": "درجات التدريب تظهر فورًا في «تدريبي». أما «نتائجي» فهي لاختبارات نافس الرسمية التي يرسلها معلمك فقط.",
