  "After reading a short story or article together, ask: “What is it mostly about?” Let your child answer in one sentence.": "بعد قراءة قصة قصيرة أو مقال معًا، اسألوا: «عمّ يتحدث النص في الغالب؟» ودعوا طفلكم يجيب بجملة واحدة.",
  "Finding details in the text": "إيجاد التفاصيل في النص",
  "Ask one question about a page you read together and let your child point to the sentence that answers it.": "اطرحوا سؤالًا واحدًا عن صفحة قرأتموها معًا، ودعوا طفلكم يشير إلى الجملة التي تجيب عنه.",
  "Reading between the lines": "فهم ما بين السطور",
  "When your child tells you how a character feels, ask: “How do you know?” and look for the clue together.": "عندما يخبركم طفلكم بشعور إحدى الشخصيات، اسألوا: «كيف عرفت؟» وابحثوا عن الدليل معًا.",
  "Understanding stories": "فهم القصص",
  "Ask your child to retell a story you read together: the beginning, the middle and the end.": "اطلبوا من طفلكم أن يعيد سرد قصة قرأتموها معًا: البداية والوسط والنهاية.",
  "Understanding information texts": "فهم النصوص المعلوماتية",
  "Read a short news item, recipe or leaflet together and ask: “What does the writer want us to know?”": "اقرؤوا معًا خبرًا قصيرًا أو وصفة طعام أو نشرة، واسألوا: «ماذا يريدنا الكاتب أن نعرف؟»",
  "Learning new words": "تعلّم كلمات جديدة",
  "Choose three new words this week (from a book, a sign or the news) and use each one in a sentence at dinner.": "اختاروا ثلاث كلمات جديدة هذا الأسبوع (من كتاب أو لافتة أو الأخبار) واستخدموا كل كلمة في جملة على العشاء.",
  "Writing correct sentences": "كتابة جمل صحيحة",
  "Write a short message or shopping list together, then check it: does each sentence start with a capital letter and end with a full stop?": "اكتبوا معًا رسالة قصيرة أو قائمة مشتريات، ثم راجعوها: هل تبدأ كل جملة بحرف كبير وتنتهي بنقطة؟",
  "Spelling and punctuation": "الإملاء وعلامات الترقيم",
  "Dictate three short sentences; your child writes them, then you check the spelling and the full stops together.": "أملوا ثلاث جمل قصيرة يكتبها طفلكم، ثم راجعوا الإملاء والنقاط معًا.",
  "Reading aloud smoothly": "القراءة الجهرية بطلاقة",
  "Read aloud together for 10 minutes: take turns reading a page, slowly and clearly.": "اقرؤوا جهرًا معًا مدة 10 دقائق: تناوبوا على قراءة صفحة ببطء ووضوح.",
  "Writing a few sentences": "كتابة بضع جمل",
  "Ask your child to write three sentences about their day, then read them aloud to you.": "اطلبوا من طفلكم أن يكتب ثلاث جمل عن يومه، ثم يقرأها لكم بصوت عالٍ.",
  "Reading every day": "القراءة كل يوم",
  "Read together for 15 minutes a day and talk about the book: what did you like, and why?": "اقرؤوا معًا 15 دقيقة يوميًا وتحدثوا عن الكتاب: ماذا أعجبك، ولماذا؟",
  "Each student's week in simple words for the family: what they worked on, things to practise at home and your note. Preview it, then download a PDF to send by WhatsApp.": "أسبوع كل طالب بكلمات بسيطة للعائلة: ما عمل عليه، وأشياء للتدرّب عليها في البيت، وملاحظتك. اعرضه أولًا، ثم نزّل ملف PDF لإرساله عبر واتساب.",
