  "Print this page at 100% (no “fit to page”).": "اطبع هذه الصفحة بنسبة 100% (بدون «ملاءمة الصفحة»).",
  "Fill the {n} questions with a pencil exactly as the key beside the bubbles says (it includes a light mark, an erased answer, an empty one and a double mark on purpose).": "ظلّل الأسئلة الـ{n} بقلم رصاص كما يقول المفتاح بجانب الدوائر تمامًا (يتضمن عمدًا علامة خفيفة وإجابة ممسوحة وسؤالًا فارغًا وعلامة مزدوجة).",
  "Put the sheet on a table and take a photo with your phone: the whole sheet with its four black corner squares, any angle.": "ضع الورقة على طاولة والتقط صورة بهاتفك: الورقة كاملة مع المربعات السوداء الأربعة في زواياها، من أي زاوية.",
  "Choose the photo below (or use the camera): it is read on this device and compared with the key. Nothing is uploaded or saved.": "اختر الصورة أدناه (أو استخدم الكاميرا): تُقرأ على هذا الجهاز وتُقارن بالمفتاح. لا يُرفع أو يُحفظ أي شيء.",
  "Answer key: fill exactly this": "مفتاح الإجابة: ظلّل هذا تمامًا",
  "Fill the bubbles as the key on the right says, then photograph the sheet and check it on the trial page.": "ظلّل الدوائر كما يقول المفتاح على اليمين، ثم صوّر الورقة وتحقّق منها في صفحة التجربة.",
  "A good reader reads every normal mark, reads or asks about the light one, and ASKS about the double mark — it never guesses.": "القارئ الجيد يقرأ كل علامة عادية، ويقرأ العلامة الخفيفة أو يسأل عنها، ويسأل عن العلامة المزدوجة — ولا يخمّن أبدًا.",
  "Check my photo": "تحقّق من صورتي",
  "Print a trial sheet": "اطبع ورقة تجربة",
  "A sample test of 20 answers with its key: fill it, photograph it and see what the reader reads.": "اختبار تجريبي من 20 إجابة مع مفتاحه: ظلّله وصوّره وشاهد ما يقرؤه القارئ.",
  "Clear sheet: every answer was read with confidence.": "ورقة واضحة: قُرئت كل الإجابات بثقة.",
