  "Low confidence: check every answer, or take the photo again.": "ثقة منخفضة: تحقّق من كل إجابة، أو التقط الصورة مرة أخرى.",
  "the photo is blurry": "الصورة غير واضحة",
  "the photo is dark or the marks are faint": "الصورة داكنة أو العلامات باهتة",
  "the sheet is hard to line up (folded, cut off or very tilted)": "يصعب ضبط الورقة (مطوية أو مقصوصة أو مائلة جدًا)",
  "many marks are unclear": "كثير من العلامات غير واضحة",
