  "Some answers still need checking: pick an answer (or No answer) for every highlighted question.": "ما زالت بعض الإجابات تحتاج إلى مراجعة: اختر إجابة (أو «لا إجابة») لكل سؤال مظلَّل.",
  "This photo was read with low confidence: check every answer against the paper first.": "قُرئت هذه الصورة بثقة منخفضة: راجع كل إجابة مقابل الورقة أولًا.",
  "Sent automatically": "أُرسل تلقائيًا",
