  "Off for the school": "متوقف للمدرسة",
  "Only you assign lessons, except when the platform sees a clear, strong problem on one skill: then it sends the lesson for that skill by itself (at most one a week per student). Keep it, undo it before the student starts, or change it.": "أنت وحدك من يُسند الدروس، إلا عندما ترى المنصة مشكلة واضحة وقوية في مهارة واحدة: عندها ترسل درس تلك المهارة تلقائيًا (درسًا واحدًا في الأسبوع لكل طالب على الأكثر). أبقِه، أو تراجع عنه قبل أن يبدأ الطالب، أو غيّره.",
