  "Every source": "كل المصادر",
  "Each student starts at Medium: a right answer brings a harder question, a wrong answer an easier one, inside the chosen standards.": "يبدأ كل طالب بمستوى متوسط: الإجابة الصحيحة تأتي بسؤال أصعب، والإجابة الخاطئة بسؤال أسهل، ضمن المعايير المختارة.",
  "One builder: start from a model booklet, all 13 standards, or the standards you choose; then the number of questions, the time, the difficulty (Easy, Medium, Hard, Mixed or Adaptive) and test or practice.": "أداة واحدة للبناء: ابدأ من كتيّب نموذجي، أو من المعايير الثلاثة عشر كلها، أو من المعايير التي تختارها؛ ثم عدد الأسئلة والوقت ومستوى الصعوبة (سهل، متوسط، صعب، مختلط أو تكيفي) واختبار أو تدريب.",
  "Choose a model booklet (or a random one).": "اختر كتيّبًا نموذجيًا (أو كتيّبًا عشوائيًا).",
  "Tick standards or skills, or add questions from the bank below.": "حدّد معايير أو مهارات، أو أضف أسئلة من البنك أدناه.",
