  "All standards and skills": "كل المعايير والمهارات",
  "New, original questions written by AI from the NAFS blueprint and the 13 Ministry standards (MCQ A–D, Grade 6). Check each one, then approve it to add it to the test. Only curriculum data is sent — never student data.": "أسئلة جديدة وأصلية يكتبها الذكاء الاصطناعي وفق مخطط نافس والمعايير الثلاثة عشر للوزارة (اختيار من متعدد أ–د، الصف السادس). راجع كل سؤال ثم اعتمده لإضافته إلى الاختبار. تُرسل بيانات المنهج فقط — ولا تُرسل بيانات الطلاب أبدًا.",
  "Write the questions": "اكتب الأسئلة",
  "Approve all and add": "اعتمد الكل وأضفه",
  "Approve and add": "اعتمد وأضف",
  "Drafts you do not approve stay in the Question bank for review.": "المسودات التي لا تعتمدها تبقى في بنك الأسئلة للمراجعة.",
  "Adapt over every center question of these standards (not only this list)": "التكيّف على كل أسئلة المركز لهذه المعايير (وليس هذه القائمة فقط)",
  "Choose the class first": "اختر الفصل أولًا",
