  "adaptive practice on the same standards": "تدريب تكيفي على المعايير نفسها",
  "Recommended: each student starts at Medium; a right answer brings a harder question, a wrong answer an easier one. A fixed difficulty keeps the practice to questions of that difficulty.": "موصى به: يبدأ كل طالب بمستوى متوسط؛ الإجابة الصحيحة تأتي بسؤال أصعب، والخاطئة بسؤال أسهل. أما الصعوبة الثابتة فتجعل التدريب على أسئلة تلك الصعوبة فقط.",
  "The questions behind your choice": "الأسئلة التي يشملها اختيارك",
  "{n} chosen question(s): only these are used": "{n} سؤال مختار: تُستخدم هذه الأسئلة فقط",
  "Choose this page": "اختر أسئلة هذه الصفحة",
  "Choose this question": "اختر هذا السؤال",
  "Start from one of these; then set the questions, the time, the difficulty and test or practice.": "ابدأ من أحد هذه الخيارات؛ ثم حدّد الأسئلة والوقت ومستوى الصعوبة واختبارًا أو تدريبًا.",
  "No NAFS tests yet. Start with a model booklet or all 13 standards.": "لا توجد اختبارات نافس بعد. ابدأ بكتيّب نموذجي أو بالمعايير الثلاثة عشر كلها.",
  "A model booklet": "كتيّب نموذجي",
  "One of the model booklets as it is (or fewer questions picked by the standards) — choose one, or a random one.": "أحد الكتيّبات النموذجية كما هو (أو أسئلة أقل تُختار حسب المعايير) — اختر كتيّبًا أو كتيّبًا عشوائيًا.",
  "All 13 standards — complete test": "المعايير الثلاثة عشر كلها — اختبار كامل",
  "Every Ministry standard in the guide's proportions, an informational and a literary text, the PIRLS processes; you check the coverage before saving.": "كل معايير الوزارة بنسب الدليل، ونص معلوماتي ونص أدبي، وعمليات PIRLS؛ وتراجع التغطية قبل الحفظ.",
  "Choose standards / skills myself": "أختار المعايير / المهارات بنفسي",
  "Tick standards or NAFS skills: balanced over your choice, or shaped like the real booklet. Or add questions one by one.": "حدّد معايير أو مهارات نافس: موزّعة بالتساوي على اختيارك، أو بشكل الكتيّب الحقيقي. أو أضف الأسئلة واحدًا واحدًا.",
  "1. Start from · 2. Options · 3. The questions — replace, remove, reorder or add any question before saving.": "١. ابدأ من · ٢. الخيارات · ٣. الأسئلة — استبدل أي سؤال أو احذفه أو أعد ترتيبه أو أضف أسئلة قبل الحفظ.",
  "Adaptive test: online, each student starts at Medium and the next question is harder after a right answer, easier after a wrong one, inside the test's standards (results under Practice). Printed, it is the Mixed list below.": "اختبار تكيفي: عبر الإنترنت يبدأ كل طالب بمستوى متوسط، ويكون السؤال التالي أصعب بعد الإجابة الصحيحة وأسهل بعد الخاطئة، ضمن معايير الاختبار (النتائج في التدريب). أما المطبوع فهو القائمة المختلطة أدناه.",
  "Adaptive test given online to {n} student(s): each one starts at Medium and the questions adapt. Results are under Practice.": "أُعطي الاختبار التكيفي عبر الإنترنت لـ {n} طالب: يبدأ كلٌّ منهم بمستوى متوسط وتتكيّف الأسئلة. النتائج في التدريب.",
  "Online, each student starts at Medium: a right answer brings a harder question, a wrong answer an easier one, inside the test's standards. On paper the test prints as Mixed.": "عبر الإنترنت يبدأ كل طالب بمستوى متوسط: الإجابة الصحيحة تأتي بسؤال أصعب، والخاطئة بسؤال أسهل، ضمن معايير الاختبار. وعلى الورق يُطبع الاختبار مختلطًا.",
  "After saving: assign it online (it adapts to each student) or print it (Mixed).": "بعد الحفظ: أعطه عبر الإنترنت (يتكيّف مع كل طالب) أو اطبعه (مختلط).",
