  "No goal-area score: the overall RIT is used": "لا توجد درجة للمجال: تُستخدم درجة RIT الكلية",
  "No goal-area score in the MAP file: the overall RIT is used for this area.": "لا توجد درجة لهذا المجال في ملف MAP: تُستخدم درجة RIT الكلية لهذا المجال.",
