  "the band above: the next step.": "النطاق الأعلى: الخطوة التالية.",
  "Each skill is listed once with its star; open it to see the MAP statements it covers.": "كل مهارة مذكورة مرة واحدة مع نجمتها؛ افتحها لترى عبارات MAP التي تغطيها.",
