  "Read “{title}” first, then come back and keep practising. It is your choice.": "اقرأ «{title}» أولًا ثم عد وتابع التدريب. القرار لك.",
  "Open the lesson": "افتح الدرس",
  "{n} of {total} students mastered this skill": "{n} من {total} طلاب أتقنوا هذه المهارة",
  "My star for this skill": "نجمتي في هذه المهارة",
  "You mastered this skill!": "لقد أتقنت هذه المهارة!",
  "You are learning this skill. Keep going!": "أنت تتعلّم هذه المهارة. واصل!",
  "You have not started this skill yet.": "لم تبدأ هذه المهارة بعد.",
  "A new challenge is ready for this skill.": "تحدٍّ جديد جاهز لهذه المهارة.",
  "Time to review this skill and win the star back.": "حان وقت مراجعة هذه المهارة واستعادة النجمة.",
  "No skill practice yet.": "لا تدريب على المهارة بعد.",
  "Next: assign it or practise it from a plan.": "التالي: كلّف بها أو تدرّب عليها من خطة.",
  "{n} questions without mastery": "{n} سؤالًا دون إتقان",
  "Next: the RTI plan suggests this skill.": "التالي: خطة RTI تقترح هذه المهارة.",
  "{n} questions answered, mastery {score}%": "أجاب عن {n} سؤالًا، الإتقان {score}%",
  "The star comes after at least 30 questions with mastery.": "النجمة تأتي بعد 30 سؤالًا على الأقل مع الإتقان.",
  "Mastered today after {n} questions": "أتقنها اليوم بعد {n} سؤالًا",
  "Mastered {d} days ago after {n} questions": "أتقنها قبل {d} أيام بعد {n} سؤالًا",
  "review in {d} days": "المراجعة بعد {d} أيام",
  "review check due now": "سؤال المراجعة مستحق الآن",
  "Next level": "المستوى التالي",
  "Learning": "أتعلّم",
  "Mastered 🎉": "أتقنتها 🎉",
  "New challenge": "تحدٍّ جديد",
  "Review time": "وقت المراجعة",
  "Practising: the star comes after at least 30 questions with mastery.": "يتدرّب: النجمة تأتي بعد 30 سؤالًا على الأقل مع الإتقان.",
  "At least 30 questions and the engine's mastery. A review check comes 3 weeks later.": "30 سؤالًا على الأقل مع إتقان المحرّك. يأتي سؤال المراجعة بعد 3 أسابيع.",
