  "Built from the NAFS reports: the weakest Ministry standards per class, per group and per student. One click gives adaptive practice on exactly those standards (each student starts at Medium and the questions adapt).": "مبنية على تقارير نافس: أضعف معايير الوزارة لكل فصل ولكل مجموعة ولكل طالب. بنقرة واحدة يُعطى تدريب تكيفي على هذه المعايير تحديدًا (يبدأ كل طالب من المستوى المتوسط وتتكيف الأسئلة).",
