  "Each cell: the star and the student's level on that skill. — = not assigned to this student. Click a cell for its detail, a skill for its page.": "كل خانة: النجمة ومستوى الطالب في تلك المهارة. — = غير مكلَّف بها هذا الطالب. انقر خانة لتفاصيلها، ومهارة لصفحتها.",
