  "On track + Ready for next level.": "على المسار + جاهز للمستوى التالي.",
  "Ready for next level: every assigned skill is mastered (⭐ or ☆⬆). Need support: at least one assigned skill is “Needs support” or 🔄 Needs review. On track: everyone else.": "جاهز للمستوى التالي: كل مهارة مكلَّف بها متقنة (⭐ أو ☆⬆). يحتاج إلى دعم: مهارة مكلَّف بها واحدة على الأقل «تحتاج إلى دعم» أو 🔄 تحتاج إلى مراجعة. على المسار: الباقون.",
  "Not started yet: {n} students": "لم يبدؤوا بعد: {n} طالب",
