  "{n} skills assigned · {m} mastered · {l} learning · {r} to review": "{n} مهارة مكلَّف بها · {m} متقنة · {l} قيد التعلم · {r} للمراجعة",
  "Only the skills assigned to this student, with their source. Sending to the family goes through the school admin's approval.": "المهارات المكلَّف بها هذا الطالب فقط، مع مصدرها. الإرسال إلى الأسرة يمر بموافقة إدارة المدرسة.",
