  "Students scan it at school or at home, tap their name and type the class code. It keeps working week after week.": "يمسحه الطلاب في المدرسة أو في البيت، ويضغطون على أسمائهم ويكتبون رمز الصف. يبقى صالحًا أسبوعًا بعد أسبوع.",
  "Students scan it at school or at home and tap their name. It keeps working week after week.": "يمسحه الطلاب في المدرسة أو في البيت، ويضغطون على أسمائهم. يبقى صالحًا أسبوعًا بعد أسبوع.",
  "Weekly plan prints add this QR and code for you.": "طباعة الخطة الأسبوعية تضيف رمز QR ورمز الصف تلقائيًا.",
  "The printed QR is off. Students cannot sign in with it.": "رمز QR المطبوع متوقف. لا يستطيع الطلاب الدخول به.",
