  // Server status
  "Server status": "حالة الخادم",
  "Is the server up, does it have memory to spare, can it reach the database? Nothing here changes anything.": "هل الخادم يعمل، وهل توجد ذاكرة متاحة، وهل يستطيع الوصول إلى قاعدة البيانات؟ لا شيء هنا يغيّر أي شيء.",
  "Right now": "الآن",
  "Uptime": "مدة التشغيل",
