  "Database": "قاعدة البيانات",
  "OK": "تمام",
  "Unreachable": "لا يمكن الوصول إليها",
  "Memory is high ({used} MB of a {limit} MB busy-line). The server is pausing optional background work until it drops; students and teachers can keep using the platform.": "الذاكرة مرتفعة ({used} ميجابايت من حد {limit} ميجابايت). يوقف الخادم المؤقت الأعمال الخلفية الاختيارية حتى تنخفض؛ يمكن للطلاب والمعلمين الاستمرار في استخدام المنصة.",
  "The database could not be reached just now:": "تعذّر الوصول إلى قاعدة البيانات الآن:",
  "Memory detail": "تفاصيل الذاكرة",
  "How Node.js is using the memory the server has. RSS is the number that matters: it is what Render compares to the plan's limit.": "كيف يستخدم Node.js ذاكرة الخادم. RSS هو الرقم المهم: هو ما تقارنه Render بحد الخطة.",
  "{n} big cache build waiting its turn right now.": "{n} عملية بناء ذاكرة مؤقتة كبيرة تنتظر دورها الآن.",
  "Memory watch (the “black box”)": "رصد الذاكرة (“الصندوق الأسود”)",
  "A background watcher (src/server/monitoring/memory.ts) samples this process every 15 seconds and writes a log line when memory is high or jumps, naming the last pages opened — so a crash in Render's logs says what led to it. Full history lives in Render's own log viewer, not here; this shows this server process's most recent pages since it last started.": "يرصد برنامج خلفي (src/server/monitoring/memory.ts) هذه العملية كل 15 ثانية ويكتب سطر سجل عندما تكون الذاكرة مرتفعة أو ترتفع بسرعة، مع ذكر آخر الصفحات التي فُتحت — ليوضّح سجل Render سبب أي توقف. السجل الكامل في سجلّات Render نفسها لا هنا؛ هذا يعرض آخر صفحات هذه العملية منذ آخر تشغيل.",
  "No pages opened on this server process yet.": "لم تُفتح أي صفحة في هذه العملية حتى الآن.",
  "Related pages": "صفحات ذات صلة",
  "is the database up to date with the code?": "هل قاعدة البيانات مطابقة لآخر إصدار من الكود؟",
  "a readable Excel copy of the school's data": "نسخة Excel قابلة للقراءة من بيانات المدرسة",
  "recent application errors": "أخطاء التطبيق الأخيرة",
  "For how the database itself is backed up and restored, see docs/BACKUP-AND-RESTORE.md in the project.": "لمعرفة كيفية نسخ واستعادة قاعدة البيانات نفسها، راجع docs/BACKUP-AND-RESTORE.md في المشروع.",
