  "This week, the school": "هذا الأسبوع، المدرسة",
  "This class already has this skill assigned — assign it again?": "هذا الفصل لديه هذه المهارة معيّنة من قبل — تعيّنها مرة أخرى؟",
  "Assign again": "عيّنها مرة أخرى",
  "Stopped: the work left the students' lists. Answers already given are kept.": "تم الإيقاف: اختفى العمل من قوائم الطلاب. الإجابات اللي اتسجلت قبل كده محفوظة.",
  "Deleted for good. This cannot be undone.": "اتحذف نهائيًا. لا يمكن التراجع عن هذا.",
