  "Stop sending to students. Answers already given are kept, and the plan stays in your Finished list.": "توقف عن الوصول للطلاب. الإجابات اللي اتسجلت قبل كده تفضل محفوظة، والخطة تفضل موجودة في قائمة Finished.",
  "Stop sending to students. Answers already given are kept, and you can undo this from Assigned.": "توقف عن الوصول للطلاب. الإجابات اللي اتسجلت قبل كده تفضل محفوظة، وتقدر ترجعها من صفحة Assigned.",
  "Gone from here for good; no Undo. Answers already given are not deleted.": "هتختفي من هنا نهائيًا؛ من غير رجوع. الإجابات اللي اتسجلت قبل كده مش بتتمسح.",
  "Gone from here for good; no Undo. Work already submitted or scored stays in the history.": "هتختفي من هنا نهائيًا؛ من غير رجوع. الشغل اللي اتسلّم أو اتصحح قبل كده يفضل في السجل.",
  "Stop sending to students. Work already given is kept, and you can undo this from Assigned.": "توقف عن الوصول للطلاب. الشغل اللي اتسلّم قبل كده يفضل محفوظ، وتقدر ترجعه من صفحة Assigned.",
  "A look at this skill — the questions, not the answers. Your teacher assigns it from here when it's time to practise.": "نظرة على هذه المهارة — الأسئلة فقط، مش الإجابات. المعلم هو اللي بيكلفك بيها من هنا وقت التدريب.",
