  "NAFS vs. Motivational Practice Balance": "توازن التدريب: نافس مقابل الأنشطة المحفّزة",
  "How much of each student's practice is NAFS exam drilling versus ReadRise and games — a department-level target so NAFS does not crowd out the features that keep practice motivating.": "كم من تدريب كل طالب هو تدريب على اختبار نافس مقابل ريدرايز والألعاب — هدف على مستوى القسم بحيث لا يزاحم نافس الأنشطة التي تجعل التدريب محفّزًا.",
