  "NAFS share is NAFS minutes ÷ (NAFS + ReadRise) minutes. A student is flagged \"NAFS-heavy\" at over {p}% NAFS share, with at least {m} combined minutes (shorter samples are too noisy to flag).": "نسبة نافس = دقائق نافس ÷ (دقائق نافس + ريدرايز). يُعلَّم الطالب بأنه \"يغلب عليه نافس\" إذا زادت نسبة نافس عن {p}%، بشرط ألا يقل إجمالي الدقائق عن {m} دقيقة (الفترات الأقصر غير كافية لتصنيفها).",
  "Games have no time tracked in the platform (only questions answered), so they are shown separately and never counted in the NAFS share. Badges and streaks are not timed practice and are not part of this report.": "لا تُسجِّل المنصة وقت الألعاب (فقط عدد الأسئلة المحلولة)، لذلك تُعرض بشكل منفصل ولا تُحسب ضمن نسبة نافس. الشارات وسلاسل الأيام ليست تدريبًا مُحدَّد الوقت وليست جزءًا من هذا التقرير.",

